ts_message("chunk #38 `<load kmate allele frequencies + flower counts>` start")

# seedmix
gen0 <- fread("/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/data/PHASE_1_2_COMBINED_kmate_allele_frequency_seedmix_randswitch.csv")

# now can just read it
#hapfire <- open_dataset("/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/data/kmate_parquet_randswitch")
hapfire <- open_dataset("/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/data/PHASE_1_2_COMBINED_kmate_allele_frequency_trays_randswitch.csv", format = "csv")

# NOTE: suspected fragile regex — the "_[0-9]_" generation pattern breaks
# silently if any generation label ever has 2+ digits (currently safe: gens 0-5).
table(as.numeric(gsub("_", "", str_extract(colnames(hapfire), "_[0-9]_"))))

# hapfire <- fread("/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/data/SV_SNP_INDEL_allele_frequency_trays.csv")

# sample sizes
flower_counts <- list.files(path = class_dir, pattern = "[1-3].pools.csv", full.names = T)
flower_counts <- read_csv(flower_counts, id = "file_path")

flower_counts_2 <- list.files(path = paste0(class_dir,"phase2_matrices/"), pattern = "rowmeta.csv", full.names = T)
flower_counts_2 <- read_csv(flower_counts_2, id = "file_path")

flower_counts_2$pool <- paste(flower_counts_2$site, flower_counts_2$generation, flower_counts_2$plot, sep = "_")

flower_counts_2 <- flower_counts_2 %>%
  group_by(pool, site, generation, plot) %>%
  summarize(total_flowers = sum(flowerscollected))

flower_counts <- bind_rows(flower_counts %>% select(pool, site, generation, plot, total_flowers), flower_counts_2)

rm(flower_counts_2); gc()
ts_message("chunk #38 done")

ts_message("chunk #60 `<pi_windows_vardp_kmate>` start")
pi_windows <- fread("/global/scratch/users/milesroberts/genomes/arabidopsis_thaliana/pi_windows.bed", col.names = c("chrom", "window_pos_1", "window_pos_2"))

print(paste("Windows:", nrow(pi_windows)))

sites <- unique(gsub("_.*", "", colnames(hapfire)))

output_pi_vardp_kmate <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/pi_windows_vardp_kmate.tsv",
  sep = ""
)

check_file_exists(output_pi_vardp_kmate)

# numeric chromosome id, to match the integer chromosome column of the BED
gen0_chrom_num <- as.integer(gsub("[^0-9]", "", gen0$chrom))

for (site in sites) {
  print(paste("Site:", site))

  hap_site <- hapfire %>%
    dplyr::select(starts_with(paste(site, "_", sep = ""))) %>%
    collect()

  if (ncol(hap_site) < 2) {
    print("Too few columns. Skipping to next site...")
    next
  }

  hap_site <- hap_site %>% relocate(all_of(sort(colnames(hap_site))))

  hap_site <- cbind(gen0$X0_0_0, hap_site)
  colnames(hap_site)[1] <- paste(site, "_0_0", sep = "")

  site_mat <- as.matrix(hap_site)
  rm(hap_site); gc()

  gens <- as.integer(gsub("_", "", str_extract(colnames(site_mat), "_[0-9]_")))
  reps <- gsub("^.*_", "", colnames(site_mat))

  # variant indices for every window, computed once per site
  win_idx <- lapply(seq_len(nrow(pi_windows)), function(i) {
    which(gen0_chrom_num == pi_windows$chrom[i] &
            gen0$pos > pi_windows$window_pos_1[i] &
            gen0$pos < pi_windows$window_pos_2[i])
  })

  for (exprep in unique(reps[gens >= 1])) {
    print(paste("Rep:", exprep))

    # this replicate's columns in generation order, seedmix column first
    cols <- which(reps == exprep & gens >= 1)
    if (length(cols) < 1) next
    hm <- site_mat[, c(1, cols), drop = FALSE]
    rep_gens <- gens[cols]

    rep_n <- grab_sample_sizes(flower_counts, pool, colnames(hm)[-1], 10000, total_flowers)
    # sample sizes as gene copies, matching the other kmate chunks

    rep_rows <- vector("list", nrow(pi_windows))

    for (i in seq_len(nrow(pi_windows))) {
      idx <- win_idx[[i]]

      if (length(idx) < 2) {
        # a window needs two variants to have a covariance matrix; keep it in the
        # table with NA statistics. gen is positional, exactly as gt_from_covmat()
        # labels its rows (which is inaccurate when a replicate skips a generation).
        rep_rows[[i]] <- data.frame(
          gen = seq_along(rep_gens),
          gt = NA_real_, gt_abs = NA_real_, gt_abs_2 = NA_real_, gt_pos = NA_real_,
          sum_cov = NA_real_, sum_abs_cov = NA_real_, sum_pos_cov = NA_real_,
          sum_neg_cov = NA_real_, sum_var = NA_real_, ratio = NA_real_,
          site = site,
          rep = exprep,
          chrom = pi_windows$chrom[i],
          window_pos_1 = pi_windows$window_pos_1[i],
          window_pos_2 = pi_windows$window_pos_2[i]
        )
        next
      }

      covmat <- covmat_from_pmat(hm[idx, , drop = FALSE], rep_n$total_flowers * 2, correct_for_n = T, input_asin_trans = F, procedure = "none")
      gt_result <- gt_from_covmat(covmat)

      gt_result$site <- site
      gt_result$rep <- exprep
      gt_result$chrom <- pi_windows$chrom[i]
      gt_result$window_pos_1 <- pi_windows$window_pos_1[i]
      gt_result$window_pos_2 <- pi_windows$window_pos_2[i]
      rep_rows[[i]] <- gt_result
    }

    append_table(do.call(rbind, rep_rows), output_pi_vardp_kmate)
    rm(rep_rows, hm, rep_n); gc()
  }
  rm(site_mat, win_idx); gc()
}
ts_message("chunk #60 done")

